* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; color: #172321; background: #dce8dc; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background-color: #dce8dc; background-image: radial-gradient(#bdd0c0 1.4px, transparent 1.4px); background-size: 20px 20px; }
button, input { font: inherit; }
.board { width: min(100%, 520px); padding: 30px; background: #fffdf5; border: 3px solid #172321; box-shadow: 8px 8px 0 #172321; }
.board-header { display: flex; align-items: center; gap: 16px; padding-bottom: 22px; border-bottom: 2px dashed #c7d1c6; }
.brand-mark { width: 56px; height: 56px; display: grid; place-items: center; flex: 0 0 auto; color: #fffdf5; background: #e66b4e; border: 3px solid #172321; box-shadow: 3px 3px 0 #172321; font-size: 32px; }
.eyebrow, .sort-note, footer, .optional { font-size: 12px; font-weight: 800; letter-spacing: .1em; }
.eyebrow { margin: 0 0 4px; color: #587169; }
h1 { margin: 0; font-size: clamp(24px, 6vw, 30px); line-height: 1.15; letter-spacing: -.04em; }
.summary { display: flex; align-items: center; gap: 10px; margin: 22px 0; padding: 13px 16px; background: #e9f1e6; border: 2px solid #172321; font-size: 16px; }
.summary strong { font-size: 20px; }
.status-dot { width: 12px; height: 12px; border: 2px solid #172321; background: #83b38b; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
legend { margin-bottom: 12px; font-size: 18px; font-weight: 800; }
.time-fields { display: flex; align-items: end; gap: 10px; }
.time-fields label, .label-field { display: grid; gap: 6px; font-weight: 700; }
.time-fields input { width: 100%; }
.time-fields label { flex: 1; }
.time-colon { padding-bottom: 8px; font-size: 25px; font-weight: 800; }
input { min-width: 0; padding: 11px 12px; color: #172321; background: #fff; border: 2px solid #172321; border-radius: 0; }
input::placeholder { color: #8a9890; }
input:focus-visible, button:focus-visible { outline: 3px solid #e66b4e; outline-offset: 3px; }
.label-field { margin-top: 14px; }
.optional { margin-left: 5px; color: #708179; font-size: 10px; }
.add-button { width: 100%; margin-top: 16px; padding: 12px 16px; border: 2px solid #172321; background: #f3c85b; color: #172321; font-weight: 800; cursor: pointer; box-shadow: 3px 3px 0 #172321; transition: transform .12s, box-shadow .12s, background .12s; }
.add-button span { font-size: 21px; vertical-align: -1px; }
button:hover { background-color: #f7d577; }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #172321; }
.alarms-section { margin-top: 30px; }
.section-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding-bottom: 10px; border-bottom: 2px solid #172321; }
h2 { margin: 0; font-size: 19px; }
.sort-note { color: #708179; font-size: 10px; }
.alarm-list { display: grid; gap: 10px; margin: 12px 0 0; padding: 0; list-style: none; }
.alarm-row { display: flex; align-items: center; gap: 12px; padding: 12px; border: 2px solid #c7d1c6; background: #fff; }
.alarm-row.is-off { opacity: .62; }
.alarm-time { min-width: 88px; font-size: 25px; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
.alarm-meta { min-width: 0; flex: 1; }
.alarm-label { overflow-wrap: anywhere; font-weight: 700; }
.alarm-state { margin-top: 2px; color: #708179; font-size: 13px; }
.row-actions { display: flex; align-items: center; gap: 8px; }
.toggle-label { display: flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; cursor: pointer; }
.toggle-label input { width: 19px; height: 19px; margin: 0; accent-color: #588a64; }
.delete-button { min-width: 40px; min-height: 40px; padding: 6px; border: 2px solid #172321; background: #fffdf5; color: #172321; font-weight: 800; cursor: pointer; }
.delete-button:hover { background: #f8ddd3; }
.empty-state { margin: 16px 0 0; padding: 18px 12px; color: #61746b; background: #f2f4ec; text-align: center; }
footer { margin-top: 26px; padding-top: 14px; border-top: 2px dashed #c7d1c6; color: #708179; text-align: center; font-size: 10px; }
footer span { margin-left: 5px; color: #e66b4e; }
@media (max-width: 420px) { body { padding: 20px 14px; } .board { padding: 22px 18px; box-shadow: 5px 5px 0 #172321; } .alarm-row { gap: 8px; padding: 10px 8px; } .alarm-time { min-width: 74px; font-size: 23px; } .row-actions { gap: 6px; } .toggle-label { gap: 4px; font-size: 12px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }

const form = document.getElementById('alarm-form');
const hourInput = document.getElementById('alarm-hour');
const minuteInput = document.getElementById('alarm-minute');
const labelInput = document.getElementById('alarm-label');
const alarmList = document.getElementById('alarm-list');
const emptyState = document.getElementById('empty-state');
const activeCount = document.getElementById('active-count');

let nextId = 1;
let alarms = [];

function render() {
  alarms.sort((a, b) => a.hour * 60 + a.minute - (b.hour * 60 + b.minute) || a.id - b.id);
  alarmList.replaceChildren();
  let enabled = 0;

  for (const alarm of alarms) {
    if (alarm.enabled) enabled += 1;
    const item = document.createElement('li');
    item.className = `alarm-row${alarm.enabled ? '' : ' is-off'}`;

    const time = document.createElement('time');
    time.className = 'alarm-time';
    time.dateTime = `${String(alarm.hour).padStart(2, '0')}:${String(alarm.minute).padStart(2, '0')}`;
    time.textContent = time.dateTime;

    const meta = document.createElement('div');
    meta.className = 'alarm-meta';
    const label = document.createElement('div');
    label.className = 'alarm-label';
    label.textContent = alarm.label || 'Alarm';
    const state = document.createElement('div');
    state.className = 'alarm-state';
    state.textContent = alarm.enabled ? 'Ready' : 'Paused';
    meta.append(label, state);

    const actions = document.createElement('div');
    actions.className = 'row-actions';
    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle-label';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = alarm.enabled;
    toggle.setAttribute('aria-label', `Turn ${time.textContent}${alarm.label ? ` ${alarm.label}` : ''} ${alarm.enabled ? 'off' : 'on'}`);
    toggle.addEventListener('change', () => {
      alarm.enabled = toggle.checked;
      render();
    });
    toggleLabel.append(toggle, document.createTextNode('On'));

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete ${time.textContent}${alarm.label ? ` ${alarm.label}` : ''}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter((entry) => entry.id !== alarm.id);
      render();
    });

    actions.append(toggleLabel, remove);
    item.append(time, meta, actions);
    alarmList.append(item);
  }

  activeCount.textContent = String(enabled);
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;
  alarms.push({
    id: nextId++,
    hour: Number(hourInput.value),
    minute: Number(minuteInput.value),
    label: labelInput.value.trim(),
    enabled: true
  });
  form.reset();
  hourInput.focus();
  render();
});

render();
